\begin{figure}[h]
\centering
\includegraphics[width=\columnwidth]{../../results/x2/fig_x2_gradient.pdf}
\caption{Share of \idk{} replies by popularity tenth, for questions with 0, 1 to 8, and 9 or 10 of 10 forced answers correct. 95\% intervals resample questions.}
\label{fig:range}
